"""
Rewrite prompts.json with an original design brief per vehicle (19 Nov 2026). The first plain prompts came back as real
cars (Matiz/Spark, Nissan Cube, Toyota Innova, Mitsubishi Delica), so every vehicle now gets its own set of design
features plus the real models of its kind it must not look like. Run once: python briefs.py
"""
import json, os
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), "prompts.json")
d = json.load(open(P, encoding="utf-8"))

ORIGINAL = (" Design it from scratch: combine the specific design features listed for this vehicle so that nobody could name a"
            " real make or model from it. It must not look like any production vehicle, and not like models by Maruti Suzuki,"
            " Hyundai, Tata, Mahindra, Toyota, Honda, Kia, Renault, Nissan, Chevrolet, Daewoo, Mitsubishi, Volkswagen, Skoda,"
            " Hero, Bajaj, TVS, Royal Enfield, Yamaha, Ola, Ather, Piaggio, Ashok Leyland, Eicher or Force Motors.")
if "Design it from scratch" not in d["style"]:
    d["style"] = d["style"].replace("Everyday Indian look of the 2020s,", ORIGINAL.strip() + " Everyday Indian look of the 2020s,")

B = {
 "car_hatch_small": "A small five-door city hatchback, original design: a short sloping bonnet; rectangular headlamps with rounded inner corners joined by a body-coloured bar; a wide trapezoid lower air intake; a flat window line that kicks up sharply at the rear door; a thick C-pillar with a small triangular quarter window; flared square wheel arches with black trims; a black roof; painted bright red. It must not look like a Matiz, Spark, Alto, Kwid, Santro or i10.",
 "car_tallboy": "A tall-boy five-door hatchback, original design: a tall upright roof with a slight rearward slope, a steeply raked windscreen, narrow headlamps that wrap round the front corners and rise up into the fenders, a closed body-coloured upper grille with a slim black slot below, one straight horizontal crease along the whole side above the door handles, a vertical tail-lamp strip up each rear pillar, a dark grey band along the bottom of the doors, painted silver. It must not look like a Wagon R, Nissan Cube, Santro Xing, Celerio or S-Presso.",
 "car_sedan_compact": "A compact four-door notchback sedan, original design: a low wide front with thin LED headlamps linked by a light bar, a hexagonal lower grille with plain mesh, a sharp shoulder line rising toward the rear, a short high boot with a small integrated spoiler lip, black window frames, painted pearl white. It must not look like a Dzire, Amaze, Aura, Tigor, Vento, Rapid or City.",
 "car_mpv_compact": "A compact seven-seat MPV, original design: a short bonnet flowing into a long raked windscreen, small diamond-shaped headlamps high on the front corners, a wide black lower grille shaped like an upturned trapezoid, a rising window line ending in a sharp upswept rear quarter window, a floating black roof with black pillars, roof rails, painted metallic bronze. It must not look like an Ertiga, Innova, Carens, Marazzo or Triber.",
 "car_mpv_large": "A large seven-seat MPV, original design: a tall upright nose with stacked lamps on each side (a slim LED strip above a square lamp), a wide grille of three thick horizontal body-coloured bars, a long flat roof with a slight step above the second row, big rectangular side windows with a chunky body-coloured middle pillar, a sliding rear side door with a visible rail, painted silver-grey. It must not look like an Innova, Innova Crysta, Delica, Marazzo, Carnival or Xylo.",
 "car_suv_boxy": "A rugged body-on-frame utility SUV, original design: square slab sides; a flat bonnet with a raised centre bulge; square headlamps with rounded corners set in a full-width black grille panel of coarse square mesh; thick black square wheel-arch trims; a flat roof that steps up slightly behind the front doors; a side-hinged rear door carrying the spare wheel; small square rear quarter windows; painted plain white. It must not look like a Bolero, Thar, Scorpio, Gypsy, Jimny, Sumo, Gurkha, Land Cruiser or Defender.",
 "car_suv_muscular": "A muscular mid-size SUV, original design: a high flat bonnet; split headlamps with thin LED daytime lamps on top and the main lamps low in the bumper; a tall grille of five thick horizontal bars; strongly flared square wheel arches; a rising window line with a blacked-out rear pillar; roof rails; painted metallic dark blue. It must not look like a Scorpio, XUV700, Safari, Harrier, Creta, Fortuner or Hector.",
 "car_pickup": "A single-cab pickup truck, original design: an upright cab with a rounded-square nose; round headlamps inside rectangular black pods; a grille of vertical bars; a flat steel cargo bed with drop-down sides and a guard frame behind the cab; steel wheels; cab painted white, cargo bed light grey. It must not look like a Bolero Pik-Up, Yodha, Dost, Super Carry or D-Max.",
 "car_van": "A high-roof panel van, original design: a short sloping nose with large teardrop headlamps running up beside the windscreen, a narrow black grille slot, a very tall flat roof, a sliding side door with a visible rail, two big rear doors, painted plain white. It must not look like an Eeco, Omni, Traveller, Winger or Supro.",
 "truck_light": "A light commercial truck, original design: a small flat-fronted cab with a big two-piece windscreen, square headlamps low in a black steel bumper, a ribbed front panel, a long open cargo body with tall wooden drop sides painted blue, the cab painted cream-yellow, twin tyres on the rear axle. It must not look like a Tata 407, Eicher Pro, Dost, Partner, Bolero Maxx or Canter.",
 "bike_commuter100": "A simple 100 cc commuter motorcycle, original design: a small trapezoid headlamp with a short smoked visor, a slim tank with a flat top and a sharp crease down each side, a long flat seat for two, a body-coloured long triangular side panel, a black engine and a short black exhaust with a silver heat shield, a rear grab rail, black body with plain red graphic stripes. It must not look like a Splendor, HF Deluxe, Platina, Star City, CD 110 or Shine.",
 "bike_commuter125": "A 125 cc commuter motorcycle, original design: a headlamp cowl with two small stacked LED lamps, a sculpted tank with large tank shrouds, an engine belly pan, a long seat for two, a chunky rear grab rail, metallic blue with grey graphic shapes. It must not look like a Glamour, Shine, SP 125, Raider, Pulsar 125 or Xtreme.",
 "bike_street160": "A 160 cc naked street motorcycle, original design: a compact headlamp of two slim LED bars stacked one above the other, a muscular tank with angular shrouds, a short stubby tail, split seats, an underbelly exhaust with no long side pipe, a chunky rear tyre, matte red and black. It must not look like a Pulsar, Apache, FZ, Hornet, Duke or Unicorn.",
 "bike_retro350": "A 350 cc neo-retro roadster motorcycle, original design: a squarish headlamp with rounded corners, a flat-sided fuel tank with knee recesses, a flat bench seat, a short boxy side panel, a short upswept twin-tip exhaust, twin rear shocks, forest green with cream tank panels. It must not look like a Royal Enfield Classic, Bullet, Hunter or Meteor, a Jawa, a Yezdi, a CB350 or a Triumph.",
 "bike_dualsport": "A 200 cc dual-sport motorcycle for hill roads, original design: a tall narrow front fairing with two headlamps stacked vertically, a small tinted windscreen, a high front mudguard, long-travel front forks, block-tread tyres, a long flat seat, a small rear rack, white with orange accents. It must not look like an Xpulse, Himalayan, 390 Adventure, KLX or XR.",
 "scooty_family": "A practical 110 cc family scooter, original design: a front apron with a horizontal wing-shaped headlamp across its top, indicators set in the handlebar cover, a wide flat floorboard, a long two-person seat, a body-coloured front mudguard, side panels with one sharp diagonal crease, pearl blue with a black floorboard. It must not look like an Activa, Jupiter, Access, Pleasure, Dio or Fascino.",
 "scooty_neoretro": "A neo-retro scooter, original design: a flat-faceted angular steel body with crisp creases, a hexagonal headlamp on the handlebar, a tall flat front apron, separate rider and pillion seats, a small rear rack, two-tone mint green and cream. It must not look like a Vespa, Lambretta, Chetak or Bajaj Super.",
 "scooty_electric": "A modern electric scooter, original design: a smooth sleek body with one thin LED strip across the front apron in a V shape, a flat floorboard, an angular seat, no exhaust pipe, a hub motor in the rear wheel, matte grey with a teal accent. It must not look like an Ola S1, Ather, iQube, Chetak electric or Vida.",
 "tirri_erickshaw": "An Indian battery e-rickshaw for city rides, original design: an open passenger body with a front bench for the driver and two facing rear benches for four passengers, thin steel pillars holding a flat roof with a small overhang, rolled-up side curtains, one front wheel with a short mudguard and two rear wheels, a small round headlamp on the front panel, body painted bright blue with a white roof. It must not look like a Treo, Safar or Yatri.",
 "tuktuk_auto": "An Indian passenger auto-rickshaw with three wheels, original design: a squared-off front panel with two small round headlamps side by side under a short visor, a handlebar for the driver, a bench seat for three, a rounded canvas roof on a steel frame with rolled side flaps, low steel side rails at the open sides, lower body painted green and the roof bright yellow. It must not look like a Bajaj RE, Piaggio Ape, TVS King, Alfa or Atul Gem.",
}
for v in d["vehicles"]:
    if v["name"] in B:
        v["prompt"] = B[v["name"]]
json.dump(d, open(P, "w", encoding="utf-8"), indent=2, ensure_ascii=False)
print("briefs:", sum(v["name"] in B for v in d["vehicles"]), "| style has originality:", "Design it from scratch" in d["style"])
